// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Sosyal psikoloji (zor).
const ozSocialscience10Zor = <(String, String, List<String>, String)>[
  ('1908 yılında başlığında \'sosyal psikoloji\' ifadesi geçen ilk iki ders kitabı yayımlanmıştır. Bu kitapların yazarları kimlerdir?', 'William McDougall ve Edward Ross', ['Kurt Lewin ve Leon Festinger', 'Solomon Asch ve Stanley Milgram', 'Gordon Allport ve Fritz Heider ile birlikte Wundt'], '1908\'de psikolog William McDougall ile sosyolog Edward A. Ross aynı yıl \'Social Psychology\' başlıklı kitaplar yayımlamıştır.'),
  ('İkinci Dünya Savaşı yıllarında Lewin\'in ev hanımlarıyla yaptığı çalışmalarda, sakatat gibi alışılmadık yiyeceklerin tüketimini artırmada hangi yöntemin daha etkili olduğu görülmüştür?', 'Grup tartışmasıyla birlikte karar alınması', ['Bir uzmanın verdiği tek yönlü ve ayrıntılı konferans', 'Yiyeceklerin fiyatının yükseltilmesi', 'Broşürlerin evlere tek tek dağıtılması'], 'Lewin\'in çalışmalarında grup tartışması yapıp birlikte karar veren kadınların, yalnızca konferans dinleyenlere göre bu yiyecekleri çok daha fazla kullandığı bulunmuştur.'),
  ('Tory Higgins\'in benlik farklılığı kuramına göre kişinin gerçek benliği ile \'olması gerektiğini\' düşündüğü benlik arasındaki büyük fark en çok hangi duyguya yol açar?', 'Kaygı ve suçluluk', ['Hüzün ve hayal kırıklığı', 'Coşku ve gurur', 'Öfke ve kıskançlık'], 'Higgins\'e göre gerçek-zorunlu benlik farkı kaygı, suçluluk gibi huzursuzluk duygularıyla; gerçek-ideal benlik farkı ise hüzün ve hayal kırıklığıyla ilişkilidir.'),
  ('Cadılar Bayramı\'nda yapılan bir alan çalışmasında, şeker kâsesinin arkasına ayna konulduğunda çocukların izin verilenden fazla şeker alma oranının düştüğü görülmüştür. Bu bulgu hangi kavramla açıklanır?', 'Öz farkındalığın standartlara uymayı artırması', ['Bireysizleşmenin kural ihlalini artırmış olması', 'Sosyal kaytarmanın çabayı azaltması', 'Aşırı gerekçelendirmenin isteği azaltması'], 'Ayna çocukların dikkatini kendilerine yöneltip dürüstlük standartlarını hatırlatmış ve kurala uymayı artırmıştır.'),
  ('Bir kez yerleşmiş bir inancın, onu destekleyen kanıtlar tamamen çürütüldükten sonra da sürmesine ne ad verilir?', 'İnancı sürdürme', ['Uyuyan etki', 'Salt maruz kalma', 'Aşılama'], 'Ross ve arkadaşlarının çalışmaları, kişilerin bir inanç için kendi açıklamalarını kurduktan sonra kanıt geçersiz sayılsa bile o inancı koruduğunu göstermiştir.'),
  ('Harold Kelley\'in 1950\'deki çalışmasında konuk bir öğretim görevlisi bazı öğrencilere \'oldukça sıcak\', bazılarına \'oldukça soğuk\' biri olarak tanıtılmıştır. Ders sonrasında hangi sonuç elde edilmiştir?', '\'Sıcak\' tanıtımı alanlar onu daha olumlu değerlendirmiş ve tartışmaya daha çok katılmıştır', ['İki grup onu tamamen aynı biçimde değerlendirmiştir', '\'Soğuk\' tanıtımı alanlar onu daha esprili bulmuştur', 'Öğrenciler tanıtımı hiç hatırlamamıştır'], 'Aynı dersi izlemelerine karşın ön bilgiler öğrencilerin değerlendirmesini ve etkileşim davranışını değiştirmiş, merkezi özelliklerin gerçek yaşamdaki etkisini göstermiştir.'),
  ('Bir iş görüşmesinde adayın birkaç saniyelik ilk davranışlarından görüşmecilerin uzun görüşme sonundaki kararlarıyla büyük ölçüde örtüşen yargılara varabilmesini anlatan kavram hangisidir?', 'İnce dilimleme', ['Bilişsel çelişki', 'Sosyal kaytarma', 'Grup kutuplaşması'], 'Ambady ve Rosenthal\'ın öncü çalışmaları ve onları izleyen iş görüşmesi araştırmaları, çok kısa davranış kesitlerinden yapılan değerlendirmelerin şaşırtıcı ölçüde isabetli olabildiğini göstermiştir.'),
  ('Jones ve Harris\'in 1967 deneyinde katılımcılar, yazarının konu seçme özgürlüğü olmadığı bilinen Castro yanlısı bir makaleyi okuduktan sonra bile yazarın Castro\'yu desteklediğine karar vermiştir. Bu bulgu hangi yanlılığın erken bir kanıtıdır?', 'Temel atıf hatası', ['Grup kutuplaşması', 'Kendini engelleme', 'Yanlış teklik etkisi'], 'Katılımcılar durumun zorlayıcılığını yeterince hesaba katmayıp davranışı yazarın kişisel tutumuna bağlamıştır.'),
  ('Word, Zanna ve Cooper\'ın 1974 iş görüşmesi deneylerinde siyahi adaylarla daha kısa ve mesafeli görüşen beyaz görüşmeciler gözlenmiştir. İkinci aşamada beyaz adaylarla aynı mesafeli tarzda görüşüldüğünde ne olmuştur?', 'Beyaz adaylar da daha gergin ve başarısız görünmüştür', ['Beyaz adaylar daha rahat, kendinden emin ve başarılı görünmüştür', 'Görüşme tarzının hiçbir etkisi olmamıştır', 'Görüşmeciler görüşmeyi yarıda kesmiştir'], 'Bu deney, görüşmecinin beklentisine bağlı davranışının adayın performansını değiştirerek beklentiyi doğrulattığını, yani davranışsal doğrulamayı göstermiştir.'),
  ('Snyder, Tanke ve Berscheid\'in telefon görüşmesi deneyinde erkeklerin konuştukları kadını çekici sandıklarında, kadınların daha sıcak ve sosyal davrandığı bulunmuştur. Bu bulgu hangi süreci gösterir?', 'Davranışsal doğrulama', ['Bilişsel çelişki', 'Bilişsel çelişkinin azaltılması', 'Kimliksizleşme'], 'Algılayanın beklentisi kendi davranışını, bu davranış da hedef kişinin karşılık veren davranışını etkileyerek beklentiyi gerçeğe dönüştürür.'),
  ('Rosenthal ve Fode\'nin 1963 deneyinde öğrencilere bir grup farenin labirentte \'zeki\', diğerinin \'ağır öğrenen\' soydan geldiği söylenmiş; aslında fareler rastgele ayrılmıştı. \'Zeki\' denilen farelerin daha iyi sonuç almasının açıklaması hangisidir?', 'Deneyi yapanların beklentisinin farelere davranışlarını etkilemesi', ['Farelerin gerçekten farklı soylardan gelmesi', 'Labirentlerin farklı zorlukta ve uzunlukta olması', 'Farelerin farklı yiyeceklerle beslenmesi'], 'Bu çalışma deneyci beklenti etkisini göstermiştir: beklenti, deneyi yapanların hayvanlara davranış biçimini değiştirerek sonuçlara yansımıştır.'),
  ('Planlı davranış kuramının, kendisinden önceki gerekçeli eylem kuramına eklediği öğe hangisidir?', 'Algılanan davranışsal kontrol', ['Davranışa yönelik genel tutum', 'Öznel norm', 'Davranışsal niyet'], 'Fishbein ve Ajzen\'in gerekçeli eylem kuramı tutum ve öznel normu içeriyordu; Ajzen planlı davranış kuramında kişinin davranışı yapabileceğine ilişkin algısını ekledi.'),
  ('Bir nesneyi \'iyi-kötü\', \'güçlü-zayıf\', \'aktif-pasif\' gibi karşıt sıfat çiftleri arasında derecelendirmeye dayanan anlamsal farklılık ölçeğini geliştiren araştırmacı kimdir?', 'Charles Osgood', ['Louis Thurstone', 'Rensis Likert', 'Emory Bogardus'], 'Osgood ve arkadaşlarının 1957\'de geliştirdiği anlamsal farklılık tekniği değerlendirme, güç ve etkinlik boyutlarını ölçer.'),
  ('Önce uzman yargıçların ifadeleri olumlu-olumsuz bir sürekliliğe yerleştirdiği, sonra katılımcının katıldığı ifadelerin ölçek değerlerinin ortalamasının alındığı tutum ölçeği hangisidir?', 'Thurstone ölçeği', ['Likert ölçeği', 'Anlamsal farklılık ölçeği', 'Örtük ilişkilendirme testi'], 'Louis Thurstone\'un eşit görünen aralıklar yöntemi, maddelere önceden yargıçlarca puan değeri verilmesine dayanır.'),
  ('Festinger, Riecken ve Schachter\'in \'When Prophecy Fails\' (Kehanet Başarısız Olduğunda) adlı çalışmasında, dünyanın sonunun geleceği tarihte hiçbir şey olmayınca grubun bağlı üyeleri ne yapmıştır?', 'İnançlarını daha da güçlendirip çevrelerine yaymaya başlamışlardır', ['Hemen inançlarından vazgeçmişlerdir', 'Grubu dağıtıp hiç konuşmamışlardır', 'Olayı unutup başka bir gruba katılmışlardır'], 'Kehanet için çok şey feda etmiş üyeler çelişkiyi azaltmak için \'inançlarımız dünyayı kurtardı\' açıklamasına sarılıp yeni üyeler kazanmaya çalışmıştır.'),
  ('Petty ve Cacioppo\'nun bir deneyinde üniversite öğrencilerine bitirme sınavı zorunluluğu öneren bir mesaj sunulmuştur. Önerinin kendi okullarında hemen uygulanacağını düşünen öğrenciler en çok neden etkilenmiştir?', 'Argümanların güçlü ya da zayıf olmasından', ['Konuşmacının akademik ünvanından ve kıyafetinden', 'Argüman sayısından', 'Mesajın sesinin yüksekliğinden'], 'Kişisel ilgi yüksek olduğunda öğrenciler merkezi yolu kullanmış ve güçlü argümanlarla ikna olmuş, zayıf argümanları ise reddetmiştir.'),
  ('Dennis Regan\'ın 1971 deneyinde, deneyden önce katılımcıya bir kola getiren iş birlikçi daha sonra ondan piyango bileti almasını istediğinde ne bulunmuştur?', 'Kola getirilenler, iş birlikçiyi sevmeseler bile daha çok bilet almıştır', ['Kola getirilenler hiç bilet almamıştır', 'Yalnızca iş birlikçiyi sevenler bilet almıştır', 'Kola alan ve almayan katılımcılar arasında satın alma bakımından hiç fark yoktur'], 'Regan\'ın deneyi karşılıklılık normunun, kişiye karşı duyulan hoşlanmadan bağımsız olarak güçlü bir etki yaptığını göstermiştir.'),
  ('Cialdini ve arkadaşlarının 1978 deneyinde öğrencilerden önce bir çalışmaya katılmaları istenmiş, kabul ettikten sonra çalışmanın sabah saat 7\'de olduğu söylenmiştir. Bu durumda katılım oranının, saat baştan söylendiği duruma göre yüksek çıkması hangi tekniği kanıtlar?', 'Alçak top', ['Kapıyı yüzüne çarpma', 'Ayağını kapıya sokma', 'Karşılıklılık'], 'Önce kabul ettirip sonra maliyeti artırmak alçak top tekniğidir; bu deneyde gelme oranı saat önceden söylenenlere göre belirgin biçimde yüksek bulunmuştur.'),
  ('Freedman ve Fraser\'ın 1966 çalışmasında ev sahiplerinden önce pencerelerine \'Dikkatli sürün\' yazılı küçük bir kart koymaları istenmiştir. Daha sonra yapılan istek neydi?', 'Bahçelerine büyük ve çirkin bir \'Dikkatli sürün\' tabelası dikmeleri', ['Bölgedeki bir yardım kuruluşuna düzenli olarak para bağışı yapmaları', 'Bir anket formu doldurmaları', 'Komşularına mektup yazmaları'], 'Küçük isteği kabul edenlerin büyük tabelayı kabul etme oranı, doğrudan büyük istekle karşılaşanlara göre çok daha yüksek bulunmuştur.'),
  ('Jacobs ve Campbell\'in 1961 çalışmasında otokinetik deneyde iş birlikçilerin yerleştirdiği abartılı bir norm, grup üyeleri birer birer değiştirilse de birkaç \'kuşak\' boyunca sürmüştür. Bu bulgu neyi gösterir?', 'Keyfi normların bile yeni üyelere aktarılarak kalıcılaşabileceğini', ['Normların hemen ortadan kalktığını', 'Yeni üyelerin grubun normlarını hiçbir zaman benimsemediğini', 'Normların yalnızca liderle sürdüğünü'], 'Norm, onu başlatan kişiler gruptan ayrıldıktan sonra da azalarak birkaç kuşak sürmüş; böylece kültürel aktarımın deneysel bir modeli sunulmuştur.'),
  ('Asch\'in çizgi deneyi çeşitlemelerinde, gruptaki iş birlikçi sayısı artırıldığında uymanın nasıl değiştiği bulunmuştur?', 'Üç kişiye kadar hızla artıp sonra fazla değişmemiştir', ['Grup büyüdükçe sürekli ve doğrusal olarak artmıştır', 'Tek bir iş birlikçiyle en yüksek düzeye çıkmıştır', 'Grup büyüdükçe azalmıştır'], 'Asch\'in bulgularına göre bir iş birlikçinin etkisi çok azdır; üç iş birlikçide uyma belirgin biçimde yükselir ve daha büyük gruplarda kayda değer artış görülmez.'),
  ('Moscovici ve arkadaşlarının 1969 deneyinde altı kişilik gruplara mavi renkte slaytlar gösterilmiş, gruptaki iki iş birlikçi bunları \'yeşil\' olarak nitelemiştir. Hangi koşulda gerçek katılımcıların \'yeşil\' deme oranı daha yüksek olmuştur?', 'İş birlikçiler her denemede tutarlı biçimde \'yeşil\' dediğinde', ['İş birlikçiler bazı denemelerde \'yeşil\', bazı denemelerde \'mavi\' dediğinde', 'İş birlikçiler hiç yanıt vermediğinde', 'Katılımcılar tek başına yanıt verdiğinde'], 'Tutarlı azınlık koşulunda katılımcıların yaklaşık yüzde 8\'i \'yeşil\' derken tutarsız azınlık koşulunda bu oran yüzde 1\'in altında kalmıştır.'),
  ('Milgram\'ın, katılımcıların itaatini açıklamak için önerdiği ve bireyin kendini başkasının isteklerini yerine getiren bir araç olarak görüp sorumluluğu yetkeye devretmesini anlatan kavram hangisidir?', 'Ajantik durum', ['Özerk (otonom) durum', 'Bilişsel çelişki', 'Bireysizleşme'], 'Milgram\'a göre ajantik durumdaki kişi eylemlerinin sorumluluğunu emri veren yetkeye yükler ve vicdani denetimini askıya alır.'),
  ('Charles Hofling\'in 1966 hastane çalışmasında, telefonla kendini doktor olarak tanıtan bir kişi hemşirelerden bilinmeyen bir ilacı güvenli dozun iki katı oranında vermelerini istemiştir. Sonuç ne olmuştur?', 'Hemşirelerin 22\'den 21\'i ilacı vermek üzere hazırlanmıştır', ['Hemşireler talimata uymayı reddedip telefonu kapatmıştır', 'Hemşirelerin yarısı doktoru şikâyet etmiştir', 'Hemşireler ilacı hemen başhekime götürmüştür'], 'Hemşirelerin yaklaşık yüzde 95\'i kurallara aykırı olmasına karşın talimata uymaya hazırlanmış ve bu, gerçek bir kurumsal ortamda yetkeye itaati göstermiştir.'),
  ('Jerry Burger\'ın 2009\'da Milgram deneyini etik kurallara uygun biçimde yenilediği çalışmada deney hangi noktada durdurulmuştur?', '150 voltta', ['450 voltta, yani en yüksek düzeyde', '15 voltta', '300 voltta'], 'Burger, 150 volttan sonra devam edenlerin çoğunun 450 volta kadar gittiği bilgisine dayanarak deneyi orada durdurmuş ve itaat oranlarının Milgram\'ın bulgularına yakın kaldığını göstermiştir.'),
  ('Milgram\'ın itaat araştırmalarını ilk kez yayımladığı makalenin yılı ve bunları ayrıntılı anlattığı kitabın adı hangisidir?', '1963; Obedience to Authority', ['1951; The Authoritarian Personality', '1971; The Lucifer Effect', '1959; When Prophecy Fails'], 'Milgram ilk bulgularını 1963\'te yayımlamış, deneylerinin bütününü 1974\'te \'Obedience to Authority\' adlı kitabında anlatmıştır.'),
  ('Zajonc ve arkadaşlarının 1969 deneyinde hamamböcekleri basit bir koridorda ve karmaşık bir labirentte, başka hamamböceklerinin izlediği ve izlemediği durumlarda koşturulmuştur. Sonuç ne olmuştur?', 'İzleyici varken basit koridorda daha hızlı, karmaşık labirentte daha yavaş koşmuşlardır', ['İzleyici varken her iki ortamda da hamamböcekleri daha hızlı koşmuştur', 'İzleyici varken her iki ortamda da daha yavaş koşmuşlardır', 'İzleyicinin hiçbir etkisi olmamıştır'], 'Hayvanlarla bile elde edilen bu sonuç, sosyal kolaylaştırmanın bilinçli değerlendirme kaygısı gerektirmeyen bir uyarılma etkisi olduğu görüşünü desteklemiştir.'),
  ('Nickolas Cottrell\'e göre sosyal kolaylaştırmayı yaratan şey başkalarının salt varlığı değil, hangi etkendir?', 'Değerlendirilme kaygısı', ['Görevin zorluk düzeyi', 'Ortamın sıcaklığı', 'Kişinin yaşı'], 'Cottrell\'in deneylerinde göz bağlı izleyicilerin bulunduğu durumda kolaylaştırma etkisi görülmemiş; etkinin değerlendirilme beklentisinden kaynaklandığı öne sürülmüştür.'),
  ('Latané, Williams ve Harkins\'in deneylerinde gözleri bağlı ve kulaklıklı katılımcılardan bağırmaları istenmiş, bazılarına başkalarıyla birlikte bağırdıkları söylenmiştir. Bu çalışmalar sosyal kaytarmanın hangi nedenini ortaya koymuştur?', 'Eşgüdüm kaybı olmasa bile güdülenmenin azaldığını', ['Performans düşüşünün yalnızca eşgüdüm kaybından kaynaklandığını', 'Katılımcıların sesinin kısıldığını', 'Grupla bağırmanın çabayı artırdığını'], 'Katılımcılar aslında yalnız bağırdıkları halde grupla bağırdıklarını sandıklarında daha az ses çıkarmış; bu, çaba kaybının salt güdüsel olduğunu göstermiştir.'),
  ('Tuckman, 1977\'de Mary Ann Jensen ile modeline beşinci bir evre eklemiştir. Görevini tamamlayan grubun sona ermesini anlatan bu evrenin adı nedir?', 'Dağılma', ['Yeniden oluşma', 'Uzlaşma', 'Değerlendirme'], 'Dağılma evresi, geçici grupların görevini bitirdikten sonra sona ermesini ve üyelerin bu ayrılığa uyumunu anlatır.'),
  ('Lewin ve arkadaşlarının liderlik deneyinde, otoriter liderle yönetilen gruplarda gözlenen tipik sorun hangisidir?', 'Üyeler arasında düşmanlık ya da aşırı boyun eğme ve liderin yokluğunda işi bırakma', ['Grubun hiçbir ürün ortaya koyamaması', 'Üyelerin lideri çok sevmesi', 'Grupların kendiliğinden dağılması'], 'Otoriter gruplarda üretim lider varken yüksek olsa da saldırganlık, günah keçisi arama ya da edilgen bağımlılık gözlenmiştir.'),
  ('Fiedler, liderlerin görev odaklı mı yoksa ilişki odaklı mı olduğunu belirlemek için hangi ölçeği kullanmıştır?', 'En az tercih edilen çalışma arkadaşı ölçeği', ['Bogardus sosyal uzaklık ölçeği', 'F ölçeği', 'Likert tutum ölçeği'], 'LPC ölçeğinde lider, birlikte çalışmaktan en az hoşlandığı kişiyi değerlendirir; bu kişiyi olumlu tanımlayan liderler ilişki odaklı sayılır.'),
  ('Morton Deutsch ve Robert Krauss\'ın 1960 \'kamyon oyunu\' deneyinde, oyunculara rakibin yolunu kapatabilecekleri kapılar verildiğinde ne olmuştur?', 'Her iki oyuncunun kazancı da azalmıştır', ['Her iki oyuncunun kazancı da artmıştır', 'Yalnızca kapıyı ilk kullanan oyuncu kazanmıştır', 'Oyuncular kapıları hiç kullanmamıştır'], 'Tehdit araçlarının bulunması karşılıklı tehdit ve inatlaşmaya yol açmış; özellikle iki tarafın da kapısı olduğunda kayıplar en yüksek olmuştur.'),
  ('Adorno ve arkadaşlarına göre otoriter kişiliğin kökeninde hangi çocukluk deneyimi yatmaktadır?', 'Sert, cezalandırıcı ve koşullu sevgi gösteren bir yetiştirilme', ['Aşırı hoşgörülü, kuralsız ve sınırların hiç konmadığı bir aile ortamı', 'Çok kültürlü bir okulda okumak', 'Kalabalık bir aileye sahip olmak'], 'Kurama göre sert disiplin altında büyüyen çocuklar ebeveynlerine duydukları öfkeyi bastırır ve bunu sonradan daha zayıf gruplara yöneltir.'),
  ('Toplumdaki grupların eşit olmadığını ve bazı grupların diğerlerine üstün olmasının doğal olduğunu kabul etme eğilimini ölçen kişilik özelliği hangisidir?', 'Sosyal baskınlık yönelimi', ['Biliş ihtiyacı', 'Kendini izleme (öz gözetim) eğilimi', 'Öz yeterlik'], 'Jim Sidanius ve Felicia Pratto\'nun geliştirdiği sosyal baskınlık yönelimi kavramı, gruplar arası hiyerarşiyi destekleme eğilimini anlatır ve önyargıyla ilişkilidir.'),
  ('Hamilton ve Gifford\'un 1976 deneyinde katılımcılar, azınlıktaki grubun ve seyrek görülen olumsuz davranışların birlikte daha çok görüldüğünü sanmıştır. Oysa iki grupta olumsuz davranış oranı aynıydı. Bu olguya ne ad verilir?', 'Yanılsamalı korelasyon', ['Grup kutuplaşması', 'Temel atıf hatası', 'Davranışsal doğrulama süreci'], 'Az görülen iki olayın (azınlık grubu ve olumsuz davranış) birlikte gerçekleşmesi daha dikkat çekici olduğundan aralarında olmayan bir ilişki algılanır.'),
  ('Fiske ve arkadaşlarının kalıp yargı içerik modeline göre gruplar hangi iki temel boyutta değerlendirilir?', 'Sıcaklık ve yetkinlik', ['Zekâ ve çekicilik', 'Zenginlik ve yaş', 'Dindarlık ve eğitim düzeyi'], 'Kalıp yargı içerik modeline göre gruplar, niyetlerinin iyi olup olmadığı (sıcaklık) ve bu niyetleri uygulayabilme gücü (yetkinlik) bakımından değerlendirilir.'),
  ('Kenneth ve Mamie Clark\'ın 1940\'larda siyahi çocuklara siyah ve beyaz bebekler göstererek yaptığı araştırmanın sonuçları hangi tarihi davada kanıt olarak kullanılmıştır?', 'Brown - Topeka Eğitim Kurulu davası (1954)', ['Roe - Wade davası (1973)', 'Marbury - Madison davası (1803)', 'Plessy - Ferguson davası (1896) ve sonraki temyiz süreci'], 'Clark\'ların çocukların çoğunun beyaz bebeği tercih ettiğini gösteren bulguları, okullardaki ırk ayrımının siyahi çocukların benlik algısına zarar verdiğine kanıt olarak ABD Yüksek Mahkemesi\'nde sunulmuştur.'),
  ('Pettigrew ve Tropp\'un 500\'den fazla çalışmayı birleştiren meta-analizi gruplar arası temas konusunda hangi sonuca ulaşmıştır?', 'Temasın genel olarak önyargıyı azalttığı', ['Temasın her durumda önyargıyı artırdığı', 'Temasın önyargı üzerinde hiçbir etkisinin olmadığı', 'Temasın yalnızca çocuklarda etkili olduğu, yetişkinlerde hiç işe yaramadığı'], '2006 tarihli bu meta-analiz, gruplar arası temasın önyargıyı güvenilir biçimde azalttığını, uygun koşullar varken etkinin daha da güçlendiğini göstermiştir.'),
  ('Bir dış grup üyesiyle hiç doğrudan temas kurmamış bir kişinin, kendi grubundan bir arkadaşının o gruptan biriyle yakın arkadaş olduğunu bilmesinin önyargısını azaltabilmesine ne ad verilir?', 'Dolaylı (genişletilmiş) temas etkisi', ['Salt maruz kalma etkisi', 'Sahne ışığı etkisi', 'Uyuyan etki'], 'Wright ve arkadaşlarının tanımladığı genişletilmiş temas, iç grup üyelerinin dış grupla olumlu ilişkilerini bilmenin bile önyargıyı azaltabildiğini gösterir.'),
  ('Saldırganlığın serotonin ile ilişkisine dair araştırmalar genel olarak ne göstermiştir?', 'Düşük serotonin düzeyi dürtüsel saldırganlıkla ilişkilidir', ['Yüksek serotonin düzeyi her zaman saldırganlığı artırır', 'Serotoninin saldırganlıkla hiçbir ilgisi yoktur', 'Serotonin yalnızca saldırganlığı azaltan bir ilaçtır ve vücutta doğal olarak hiç bulunmaz'], 'Hem hayvan hem insan çalışmalarında düşük serotonin düzeyinin dürtü denetimini zayıflatıp saldırgan davranış olasılığını artırdığı bulunmuştur.'),
  ('Nisbett ve Cohen\'in ABD\'nin güney eyaletlerinden gelen erkeklerin bir koridorda omuz atılıp hakarete uğradıklarında kuzeylilere göre daha öfkeli tepki verdiğini gösteren çalışmaları hangi kavramı desteklemiştir?', 'Onur kültürü', ['Bireyci kültür', 'Sosyal kaytarma', 'Grup kutuplaşması'], 'Onur kültürlerinde kişisel itibarın korunmasına büyük önem verilir ve hakarete saldırganlıkla karşılık verme toplumsal olarak beklenir.'),
  ('Latané ve Darley\'nin 1968 \'dumanlı oda\' deneyinde, odaya duman dolmaya başladığında katılımcılar tek başınayken yaklaşık yüzde 75\'i durumu bildirmiştir. Duruma tepki göstermeyen iki iş birlikçiyle birlikteyken bu oran ne olmuştur?', 'Yaklaşık yüzde 10', ['Yaklaşık yüzde 50', 'Yaklaşık yüzde 90', 'Yüzde 100, yani herkes durumu bildirmiştir'], 'Tepkisiz iş birlikçilerin varlığında katılımcıların yalnızca yaklaşık yüzde 10\'u dumanı bildirmiştir; başkalarının kayıtsızlığı durumu tehlikesiz gibi yorumlatmıştır.'),
  ('Darley ve Latané\'nin 1968\'deki interkom deneyinde, katılımcı başka bir öğrencinin nöbet geçirdiğini duyduğunda, kendisinden başka kimsenin duymadığını sandığı durumda yardım etme oranı nasıl olmuştur?', 'Çok yüksek, yaklaşık yüzde 85', ['Sıfır', 'Yaklaşık yüzde 30', 'Yaklaşık yüzde 50 ve oldukça gecikmeli'], 'Katılımcılar yalnız olduklarını sandıklarında yaklaşık yüzde 85\'i nöbet bitmeden yardıma koşmuş; dört kişi daha olduğunu sananlarda bu oran yaklaşık yüzde 31\'e düşmüştür.'),
  ('Yardım alan kişilerin bazen yardımdan rahatsızlık duyması ve kendini yetersiz hissetmesi, özellikle hangi durumda daha olasıdır?', 'Yardım, kişinin kendini değerli gördüğü bir alanda ve benzer biri tarafından yapıldığında', ['Yardım bir yabancıdan geldiğinde ve önemsiz bir konuda olduğunda', 'Yardım için açıkça istekte bulunulduğunda', 'Yardımın karşılığını hemen ödeme olanağı olduğunda ve bunu yaptığında'], 'Yardım almak kişinin özerkliğini ve yetkinlik algısını tehdit ettiğinde, özellikle benzer bir kişiden geldiğinde öz saygıyı zedeleyebilir.'),
  ('Langlois ve Roggman\'ın çalışmalarında bilgisayarla çok sayıda yüz birleştirilerek oluşturulan \'ortalama\' yüzlerin nasıl değerlendirildiği bulunmuştur?', 'Tek tek yüzlerin çoğundan daha çekici', ['Tek tek yüzlerin her birinden daha çirkin', 'Çekicilik bakımından tamamen sıradan ve ilgisiz', 'Yalnızca çocuklar tarafından beğenilen tuhaf yüzler olarak'], 'Birçok yüzün ortalaması alınarak oluşturulan yüzler, simetrik ve tanıdık göründükleri için çoğu bireysel yüzden daha çekici bulunmuştur.'),
  ('Zick Rubin\'in 1970\'te geliştirdiği ölçekler, romantik ilişkilerde hangi iki duyguyu birbirinden ayırarak ölçmeyi amaçlamıştır?', 'Hoşlanma ve sevme', ['Kıskançlık ve öfke', 'Utanç ve suçluluk', 'Kaygı ve korku ile birlikte ortaya çıkan sahiplenme'], 'Rubin\'in hoşlanma ölçeği saygı ve beğeniyi, sevme ölçeği ise bağlanma, ilgi ve yakınlığı ölçer; böylece aşkı ölçmeye yönelik ilk sistemli girişimlerden biri olmuştur.'),
  ('Aronson ve Linder\'in 1965 deneyinde katılımcılar, kendileri hakkında başta olumsuz konuşup sonra giderek olumlu konuşan bir kişiyi, hep olumlu konuşan birine göre nasıl değerlendirmiştir?', 'Daha çok sevmişlerdir', ['Daha az sevmişlerdir', 'Tamamen aynı düzeyde sevmişlerdir', 'Hiç sevmemiş ve onunla bir daha görüşmek istememişlerdir'], 'Kazanç-kayıp kuramına göre başlangıçta olumsuz olup sonra olumluya dönen değerlendirmeler, sürekli olumlu olanlardan daha çok hoşlanma yaratır.'),
  ('Uyarılmanın yanlış atfı kavramı, iki etmen kuramının hangi önermesine dayanır?', 'Duygunun fizyolojik uyarılma ve onun bilişsel yorumundan oluştuğu', ['Duygunun yalnızca kalıtımla belirlendiği', 'Uyarılmanın hiçbir zaman duygu yaratmadığı', 'Her duygunun kendine özgü ve kesin olarak ayırt edilebilen bir beden tepkisi olduğu'], 'Uyarılma belirsiz olduğunda kişi onun kaynağını ortamdaki ipuçlarına göre yorumlar; yanlış bir kaynağa yükleme de mümkündür.'),
  ('Sosyal mübadele kuramına göre ilişkisinden doyum almadığı halde başka bir seçeneği olmadığını düşünen bir kişinin ilişkiyi sürdürmesi hangi kavramla açıklanır?', 'Alternatifler için karşılaştırma düzeyinin düşük olması', ['Karşılaştırma düzeyinin çok yüksek olması', 'Tutkulu aşkın yoğunluğu', 'Kendini açmanın çok derin olması ve ilişkinin her zaman tatmin edici olması'], 'Alternatifler için karşılaştırma düzeyi, kişinin başka bir ilişkide ya da yalnız yaşamda ne elde edebileceğine dair beklentisidir; bu düşükse doyumsuz ilişkiler bile sürdürülebilir.'),
  ('John Gottman\'ın çiftlerle yaptığı araştırmalarda boşanmanın en güçlü yordayıcılarından biri olarak gördüğü ve \'kıyamet atlıları\' arasında saydığı davranışlardan biri hangisidir?', 'Aşağılama', ['Mizah', 'Sık sık birlikte yemek yeme', 'Anlaşmazlıklarda karşı tarafın duygusunu yansıtıp anlamaya çalışma'], 'Gottman\'ın dört atlısı eleştiri, aşağılama, savunmacılık ve duvar örmedir; bunlar içinde aşağılama boşanmanın en güçlü yordayıcısıdır.'),
  ('Schachter\'ın kaygı ve birliktelik çalışmasından çıkan \'Dert ortağı, dert ortağını arar\' sonucunun açıklaması hangisidir?', 'Benzer durumdakilerle karşılaştırma yaparak kendi duygularını değerlendirmek', ['Yalnızlıktan doğuştan korkmak', 'Diğerlerinden para kazanmayı ummak', 'Diğer katılımcıları deneye katılmamaları için ikna edip deneyi tamamen durdurmak'], 'Sosyal karşılaştırma kuramına uygun olarak, belirsiz ve kaygı verici durumda insanlar duygularının uygun olup olmadığını aynı durumdakilere bakarak anlamak ister.'),
  ('Beyin görüntüleme çalışmalarında sosyal dışlanmanın, beynin hangi deneyimle ilişkili bölgelerini etkinleştirdiği bulunmuştur?', 'Fiziksel acı', ['Görsel algı', 'Koku alma', 'Müzik dinlerken duyulan haz ve ödül beklentisi'], 'Eisenberger ve arkadaşlarının çalışması, dışlanmanın ön singulat korteks gibi fiziksel acıyla da ilişkili bölgeleri etkinleştirdiğini göstermiştir.'),
  ('Hall\'un kişisel alan sınıflamasında kişisel alan, sosyal alan ve genel (kamusal) alan için verilen uzaklıklar doğru sırayla hangisinde yer alır?', 'Yaklaşık 45 cm-1,2 m; 1,2-3,6 m; 3,6 m üzeri', ['Yaklaşık 0-15 cm; 15-45 cm; 45 cm üzeri', 'Yaklaşık 3-5 m; 5-10 m; 10 m üzeri', 'Yaklaşık 1,2-3,6 m; 45 cm-1,2 m; 3,6 m üzeri ve bu sıra her kültürde aynıdır'], 'Hall\'un sınıflamasında kişisel alan arkadaş sohbetleri, sosyal alan resmi etkileşimler, genel alan ise topluluk önünde konuşmalar içindir.'),
  ('Bir kişinin, karşısındakinin duruşunu, el hareketlerini ve konuşma tarzını farkında olmadan taklit etmesi ve bunun hoşlanmayı artırması hangi olguyla açıklanır?', 'Bukalemun etkisi', ['Hale etkisi', 'Silah etkisi', 'Uyuyan etki ve kaynak unutma'], 'Chartrand ve Bargh\'ın tanımladığı bukalemun etkisi, bilinçsiz taklidin etkileşimi kolaylaştırıp karşılıklı hoşlanmayı artırdığını gösterir.'),
  ('Hofstede\'nin çalışmasının ilk ve en kapsamlı verisi, 1960\'lar ve 1970\'lerde hangi kuruluşun çalışanlarından toplanmıştır?', 'IBM', ['Birleşmiş Milletler', 'Dünya Sağlık Örgütü', 'UNESCO ve Avrupa Konseyi çalışanları'], 'Hofstede, IBM\'in 50\'den fazla ülkedeki şubelerinde çalışanlara uygulanan değer anketlerini çözümleyerek kültür boyutlarını belirlemiştir.'),
  ('Türk sosyal psikolog Çiğdem Kağıtçıbaşı\'nın aile değişimi kuramında, kentleşen ve gelişen toplumlarda en sık görülen aile modeli olarak öne sürdüğü model hangisidir?', 'Duygusal (psikolojik) bağlılık modeli', ['Tam bağımsızlık modeli', 'Maddi bağlılık modeli', 'Geniş aile içinde tam ekonomik bağımlılık modeli'], 'Kağıtçıbaşı\'na göre kentleşmeyle maddi bağımlılık azalsa da duygusal bağlılık sürer; bu model özerkliği ve ilişkiselliği bir arada barındırır.'),
  ('Goldstein, Cialdini ve Griskevicius\'un 2008\'de otellerde yaptığı çalışmada, havluların yeniden kullanımını en çok artıran mesaj hangisi olmuştur?', 'Bu odada kalan konukların çoğunun havlularını yeniden kullandığını belirten mesaj', ['Çevreyi korumanın önemini anlatan genel mesaj', 'Otelin para tasarrufu yapacağını belirten mesaj', 'Havluların değiştirilmesinin yasak olduğunu ve bunun cezası bulunduğunu bildiren uyarı'], 'Konuğun kendi durumuna en çok benzeyen kişilerin davranışını bildiren betimleyici norm mesajı, standart çevre mesajından daha etkili olmuştur.'),
  ('Schultz ve arkadaşlarının elektrik tüketimi çalışmasında, ortalamanın altında elektrik harcayan evlere yalnızca \'Komşularınız ortalama şu kadar harcıyor\' bilgisi verildiğinde tüketimlerini artırdıkları görülmüştür. Bu olumsuz sonucu önlemek için ne yapılmıştır?', 'Faturaya gülen yüz simgesiyle onay işareti eklenmiştir', ['Elektrik fiyatları düşürülmüştür', 'Komşuların bilgisi tamamen gizlenmiştir', 'Bu evlerin elektriği belirli saatlerde kesilmiş ve tüketimleri zorla azaltılmıştır'], 'Betimleyici normun yarattığı \'bumerang etkisi\', düşük tüketimi onaylayan buyurucu bir ipucu (gülen yüz) eklenerek önlenmiştir.'),
  ('Zimbardo\'nun 1969 deneyinde, büyük başlıklar ve önlükler giyip isim etiketi taşımayan kadın katılımcıların, kimliği belirgin olanlara göre başka birine nasıl şok verdiği bulunmuştur?', 'İki kat kadar daha uzun süreli şok vermişlerdir', ['Hiç şok vermemişlerdir', 'Daha kısa süreli şok vermişlerdir', 'Şok düğmesine basmayı reddedip deneyi terk etmiş ve araştırmacıyı şikâyet etmişlerdir'], 'Kimliksiz bırakılan katılımcıların daha uzun şok vermesi, bireysizleşmenin ketlemeyi azaltıp zarar verici davranışı artırabileceğini göstermiştir.'),
  ('Johnson ve Downing\'in deneyinde Ku Klux Klan\'a benzer kıyafet giyenler daha çok şok verirken hemşire kıyafeti giyenler daha az şok vermiştir. Bu bulgu bireysizleşme hakkında neyi gösterir?', 'Kimliksizleşmenin, ortamdaki ipuçlarına göre olumlu ya da olumsuz davranışı artırabileceğini', ['Kıyafetin davranış üzerinde hiçbir etkisi olmadığını', 'Bireysizleşmenin her zaman saldırganlığı artırdığını', 'Hemşirelerin doğuştan daha az saldırgan olduğunu ve bunun kıyafetle ilgisi olmadığını'], 'Kıyafetin çağrıştırdığı rol ve normlar, kimliksiz kişinin davranışını yönlendirmiş; bireysizleşme bu normlara duyarlılığı artırmıştır.'),
  ('Dehşet yönetimi kuramı araştırmalarında katılımcılara kendi ölümlerini düşündüren sorular sorulduktan sonra, kendi dünya görüşlerini eleştiren kişilere karşı tepkilerinin nasıl değiştiği bulunmuştur?', 'Daha olumsuz ve cezalandırıcı hale gelmiştir', ['Daha hoşgörülü hale gelmiştir', 'Hiç değişmemiştir', 'Tamamen ilgisizleşmiş ve eleştirileri onaylamaya başlamıştır'], 'Ölümlülüğün belirginleşmesi, dünya görüşünü savunma eğilimini güçlendirir; bu da farklı düşünenlere karşı olumsuzluğu artırır.'),
  ('Sosyal yargı kuramına göre bir konuya kişisel olarak çok bağlı olan (ego katılımı yüksek) kişilerin ret alanı için ne söylenebilir?', 'Genişler; bu nedenle ikna edilmeleri zorlaşır', ['Daralır; bu nedenle kolayca ikna edilirler', 'Tamamen ortadan kalkar', 'Kabul alanıyla tamamen aynı genişliğe gelir ve iki alan birleşir'], 'Ego katılımı yüksek kişiler kendi görüşlerinden biraz farklı görüşleri bile reddeder; bu da onları iknaya dirençli kılar.'),
  ('Elliot Aronson ve arkadaşlarının \'ikiyüzlülük\' çalışmalarında öğrencilerden önce güvenli cinselliği savunan bir konuşma yapmaları, ardından bu konuda kendi geçmiş hatalarını hatırlamaları istenmiştir. Bu öğrencilerin sonradan davranışı nasıl değişmiştir?', 'Prezervatif satın alma oranları artmıştır', ['Konuyla ilgili hiçbir şey yapmamışlardır', 'Konuşmayı yapmaktan pişman olup görüşlerini değiştirmişlerdir', 'Prezervatif satın alma oranları belirgin biçimde azalmış ve konuyla ilgilenmeyi bırakmışlardır'], 'Savundukları ile yaptıkları arasındaki çelişkiyi fark eden öğrenciler çelişkiyi azaltmak için davranışlarını savundukları ilkeye uydurmuştur.'),
  ('Cooper ve Fazio\'nun \'yeni bakış\' modeline göre bilişsel çelişkinin asıl kaynağı hangisidir?', 'Kişinin istenmeyen bir sonuca kendi seçimiyle yol açtığını hissetmesi', ['İki bilişin mantıksal olarak her zaman tutarsız olması', 'Kişinin hiçbir seçim yapmamış olması', 'Kişinin yalnızca başkalarının tutarsızlığını gözlemlemesi ve bunu eleştirmesi'], 'Bu modele göre çelişki, kişinin sorumlu tutulabileceği olumsuz sonuçlar doğurduğunda ortaya çıkar; salt tutarsızlık yeterli değildir.'),
  ('Bilişsel çelişki araştırmalarında katılımcılara çelişki yaşatıldıktan sonra verilen bir hapın \'gerginlik yapabileceği\' söylendiğinde tutum değişimi azalmıştır. Bu bulgu neyi gösterir?', 'Çelişkinin hissedilen bir uyarılma olduğunu ve başka kaynağa yüklenebildiğini', ['Hapların tutumları doğrudan değiştirdiğini', 'Çelişkinin hiçbir bedensel karşılığı olmadığını', 'Katılımcıların hapı içmeyi reddettiğini ve deneyin yarıda kaldığını'], 'Zanna ve Cooper\'ın çalışmasında katılımcılar gerginliklerini hapa yükleyince tutumlarını değiştirme gereksinimi duymamıştır.'),
  ('İnsanların kendi adlarındaki harfleri ve doğum günlerindeki sayıları diğer harf ve sayılardan daha çok beğenmesine ne ad verilir?', 'Ad-harf etkisi', ['Hale etkisi', 'Salt maruz kalma etkisinin tersine dönmesi', 'Sahne ışığı etkisi ve aşırı fark edilme kaygısı'], 'Nuttin\'in ilk kez gösterdiği ad-harf etkisi, insanların benlikle ilişkili uyaranlara bilinçsiz olarak olumlu değer yüklediğini gösterir.'),
  ('Daniel Gilbert\'in atıf sürecini iki aşamalı olarak açıklayan modeline göre, zihinsel olarak meşgul (bilişsel yükü yüksek) olan bir kişinin temel atıf hatası yapma olasılığı nasıl değişir?', 'Artar; çünkü durumsal düzeltme aşaması çaba gerektirir', ['Azalır; çünkü kişi daha dikkatli düşünür', 'Hiç değişmez', 'Tamamen ortadan kalkar; çünkü kişi hiçbir atıf yapmaz ve davranışı açıklamaz'], 'Gilbert\'e göre önce otomatik olarak kişisel bir atıf yapılır, sonra çaba gerektiren bir aşamada durum hesaba katılarak düzeltilir; bilişsel yük bu düzeltmeyi engeller.'),
  ('Bond ve DePaulo\'nun 2006 meta-analizine göre sıradan insanların bir kişinin yalan söyleyip söylemediğini yalnızca davranışına bakarak ayırt etme başarısı ne düzeydedir?', 'Şans düzeyinin çok az üzerinde, yaklaşık yüzde 54', ['Neredeyse kusursuz, yaklaşık yüzde 95', 'Şans düzeyinin çok altında, yaklaşık yüzde 20', 'Uzman olmayanlarda bile yaklaşık yüzde 80'], 'Yüzlerce çalışmayı birleştiren meta-analiz, insanların yalanı doğrudan ayırt etmede şansa (yüzde 50) çok yakın bir başarı gösterdiğini bulmuştur.'),
  ('Janis ve King\'in deneylerinde, kendi görüşüne aykırı bir konuşmayı yüksek sesle hazırlayıp sunan katılımcıların, aynı konuşmayı yalnızca dinleyenlere göre tutumlarını daha çok değiştirdiği bulunmuştur. Bu olguya ne ad verilir?', 'Rol yapma yoluyla kendini ikna etme', ['Seçici maruz kalma', 'Kaynak unutma', 'Tepkisellik ve yasaklanan seçeneğe yönelme'], 'Bir görüşü etkin olarak savunmak kişinin o görüş lehine argümanlar üretmesini sağlar ve bu kendini ikna etme, pasif dinlemeden daha etkilidir.'),
  ('Ergenlik ve genç yetişkinlik yıllarının tutumların en kolay değiştiği ve sonraki yaşam için kalıplaştığı dönem olduğunu öne süren görüşe ne ad verilir?', 'Etkilenmeye açık yıllar hipotezi', ['Yaşam boyu sabitlik hipotezi', 'Tamamlayıcılık hipotezi', 'Eşleşme hipotezi ve fiziksel benzerlik'], 'Araştırmalar, siyasi ve toplumsal tutumların genç yetişkinlikte yaşanan deneyimlerle şekillendiğini ve sonra görece kararlı kaldığını göstermektedir.'),
  ('Bir kampanyada \'Siz de bu ürünü kullanmak istemez misiniz?\' gibi soru cümleleri kullanmak, alıcının ilgisi düşükse ne işe yarayabilir?', 'Alıcıyı mesaj üzerinde daha fazla düşünmeye yöneltebilir', ['Alıcının mesajı hiç duymamasını sağlar', 'Kaynağın güvenilirliğini kesin olarak düşürür', 'Mesajın uzunluğunu artırarak alıcıyı sıkar ve ürünü kesinlikle unutturur'], 'Petty ve Cacioppo\'ya göre retorik sorular, ilgisi düşük alıcıları mesajı ayrıntılı işlemeye iter; bu da güçlü argümanların etkisini artırır.'),
  ('Bibb Latané\'nin sosyal etki kuramına göre bir kaynağın birey üzerindeki etkisini belirleyen üç etken hangileridir?', 'Güç, yakınlık ve sayı', ['Yaş, cinsiyet ve meslek', 'Zekâ, çekicilik ve gelir', 'Ses tonu, kıyafet ve konuşma hızı ile birlikte beden dili'], 'Latané\'ye göre etki, kaynakların gücü (önemi), yakınlığı (anlık varlığı) ve sayısıyla artar; ancak her yeni kaynağın ek etkisi giderek azalır.'),
  ('Latané\'nin sosyal etki kuramına göre bir konserde sahneye çıkan şarkıcının sahne korkusu, izleyici sayısı 10\'dan 20\'ye çıktığında, 1000\'den 1010\'a çıktığından daha fazla artar. Bu durum hangi ilkeyle açıklanır?', 'Her ek kaynağın etkisinin giderek azalması', ['Etkinin sayıyla doğrusal olarak artması', 'İzleyici sayısının hiçbir etkisinin olmaması', 'Kalabalık büyüdükçe etkinin sürekli ve hızla artması, sınırsız büyümesi'], 'Sosyal etki kuramındaki psikososyal güç ilkesine göre ilk kaynakların etkisi büyüktür; sayı arttıkça her yeni kişinin katkısı küçülür.'),
  ('Ivan Steiner\'in görev sınıflamasında grubun başarısının en zayıf üyenin performansına bağlı olduğu görevlere ne ad verilir?', 'Bağlayıcı (conjunctive) görev', ['Toplamsal görev', 'Ayırıcı (disjunctive) görev', 'Takdire bağlı görev ve serbest seçim'], 'Dağa birlikte tırmanan bir ip takımında olduğu gibi, bağlayıcı görevlerde grup en yavaş ya da en zayıf üyesi kadar başarılıdır.'),
  ('Ryan ve Haslam\'ın \'cam uçurum\' kavramı neyi anlatır?', 'Kadınların daha çok başarısızlık riski yüksek, kriz içindeki liderlik konumlarına getirilmesini', ['Kadınların hiçbir liderlik konumuna getirilmemesini', 'Erkeklerin yalnızca kriz dönemlerinde lider olmasını', 'Cam binalarda çalışan yöneticilerin daha çok stres yaşamasını ve sık sık işten ayrılmasını'], 'Ryan ve Haslam, kadınların şirketlerin kötü performans gösterdiği dönemlerde üst yönetime atanma olasılığının daha yüksek olduğunu ve bunun başarısızlık riskini artırdığını göstermiştir.'),
  ('Meeus ve Raaijmakers\'ın 1986\'da Hollanda\'da yaptığı \'idari itaat\' deneyinde katılımcılardan ne istenmiştir?', 'İş başvurusunda bulunan birine stres yaratacak olumsuz sözler söylemeleri', ['Bir başkasına elektrik şoku vermeleri', 'Bir laboratuvar hayvanını incitmeleri', 'Bir arkadaşlarına yalan söyleyip para almaları ve bunu gizli tutmaları'], 'Fiziksel şok yerine adayı psikolojik olarak bunaltacak eleştiriler kullanılmış; katılımcıların büyük çoğunluğu (yaklaşık yüzde 90\'ı) talimatları sonuna kadar uygulamıştır.'),
  ('Fischer ve arkadaşlarının 2011 meta-analizine göre seyirci etkisi hangi tür durumlarda zayıflar?', 'Tehlikenin açık ve ciddi olduğu durumlarda', ['Hiçbir tehlikenin olmadığı durumlarda', 'Tanıkların birbirini hiç tanımadığı durumlarda', 'Olayın çok belirsiz olduğu ve kimsenin ne olduğunu anlamadığı durumlarda'], 'Tehlikeli acil durumlar daha açık biçimde tanınır ve yüksek uyarılma yaratır; ayrıca diğer tanıklar fiziksel destek olarak görülebildiğinden seyirci etkisi azalır.'),
  ('Correll ve arkadaşlarının 2002 \'nişancı yanlılığı\' çalışmasında, katılımcıların bir video oyununda silahlı ya da silahsız kişilere ateş edip etmeme kararı verirken ne bulunmuştur?', 'Siyahi hedeflerde silahsız kişilere yanlışlıkla ateş etme oranının daha yüksek olması', ['Hiçbir fark bulunmaması', 'Beyaz hedeflere her zaman daha çok ateş edilmesi', 'Katılımcıların hiç ateş etmeyi kabul etmemesi ve oyunu yarıda bırakması'], 'Siyahi hedefler silahlıyken daha hızlı ateş edilmiş, silahsızken de daha sık yanlışlıkla ateş edilmiştir; bu, otomatik kalıp yargıların hızlı kararları etkilediğini gösterir.'),
  ('Sakarlık etkisi araştırmalarına göre küçük bir hata, hangi kişinin çekiciliğini azaltır?', 'Ortalama yetenekte görünen birinin', ['Çok yetkin görünen birinin', 'Ünlü bir sporcunun', 'Bilgi yarışmasında bütün soruları doğru yanıtlamış ve herkesi şaşırtmış birinin'], 'Ortalama yetenekteki biri hata yaptığında bu onu daha da beceriksiz gösterir ve çekiciliğini düşürür.'),
  ('John Alan Lee\'nin aşk tarzları sınıflamasında, aşkı bir oyun gibi gören, bağlanmaktan kaçınan ve birden çok partnerle ilişkiyi eğlence sayan tarza ne ad verilir?', 'Ludus', ['Eros', 'Storge', 'Agape'], 'Lee\'nin sınıflamasında eros tutkulu, ludus oyunsu, storge arkadaşça, pragma pratik, mania takıntılı, agape ise özverili aşk tarzıdır.'),
  ('Pazarlıkta tarafların, kendi çıkarları ile karşı tarafın çıkarlarının mutlaka zıt olduğunu sanmasına ve böylece her iki tarafa da kazandıracak çözümleri görememesine ne ad verilir?', 'Sabit pasta yanılgısı', ['Uyuyan etki', 'Salt maruz kalma etkisi', 'Kazanç-kayıp etkisi ve beklentinin tersine dönmesi'], 'İnsanlar pazarlığı her zaman birinin kazancının diğerinin kaybı olduğu bir durum olarak algılar; oysa birçok pazarlıkta bütünleştirici, iki tarafa da yarar sağlayan çözümler vardır.'),
  ('John Calhoun\'un 1960\'larda farelerle yaptığı aşırı kalabalık deneylerinde gözlenen \'davranışsal çöküntü\' neyi anlatır?', 'Saldırganlık, yavru bakımında bozulma ve toplumsal düzenin dağılmasını', ['Farelerin daha uzun yaşayıp daha sağlıklı olmasını', 'Farelerin daha çok iş birliği yapmasını', 'Farelerin daha fazla yavru büyütüp nüfusun sürekli ve dengeli artmasını'], 'Besin ve suyun bol olmasına karşın aşırı yoğunluk farelerde saldırganlık, ilgisizlik ve anne bakımında çöküşe yol açmıştır; ancak bulguların insanlara genellenmesi tartışmalıdır.'),
  ('Glass ve Singer\'ın gürültü deneylerinde, aynı yüksek gürültüyü dinleyen katılımcılardan gürültüyü istediklerinde durdurabileceklerini bilenlerin sonraki görevlerde daha başarılı olduğu görülmüştür. Bu bulgu neyi vurgular?', 'Algılanan denetimin stres etkilerini azalttığını', ['Gürültünün performansı her zaman artırdığını', 'Düğmenin gürültüyü gerçekten azalttığını', 'Katılımcıların gürültüyü hiç duymadığını ve deneyin geçersiz olduğunu'], 'Katılımcılar düğmeye hiç basmasalar bile denetim olanağına sahip olduklarını bilmeleri, öngörülemeyen gürültünün olumsuz etkilerini hafifletmiştir.'),
  ('Masuda ve Nisbett\'in 2001 çalışmasında Japon ve Amerikalı katılımcılara bir akvaryum animasyonu izletilmiştir. Japon katılımcıların sahneyi anlatırken Amerikalılardan farklı olarak neyi daha çok söz konusu ettiği bulunmuştur?', 'Arka plandaki nesneleri ve öğeler arasındaki ilişkileri', ['Yalnızca en büyük ve en hızlı balığı', 'Akvaryumun fiyatını', 'Balıkların türlerini ve Latince adlarını tek tek sayarak bilimsel bir sınıflama yapmayı'], 'Bu bulgu Doğu Asya kültürlerinde bütüncül, Batı kültürlerinde ise odak nesneye yönelen çözümlemeci düşünme biçimlerinin baskın olduğu görüşünü desteklemiştir.'),
  ('Morris ve Peng\'in çalışmalarında aynı cinayet haberleri Çin ve ABD gazetelerinde karşılaştırıldığında, Çince gazetelerin olayları daha çok neye bağladığı bulunmuştur?', 'Durumsal ve toplumsal etkenlere', ['Katilin kişilik özelliklerine', 'Hava durumuna', 'Yalnızca katilin genetik yapısına ve çocukluk hastalıklarına'], 'Amerikan gazeteleri katilin kişisel özelliklerini öne çıkarırken Çince gazeteler ilişkiler, toplumsal baskılar ve durum gibi bağlamsal etkenleri vurgulamıştır.'),
  ('2015 yılında Açık Bilim İşbirliği\'nin psikoloji dergilerinde yayımlanmış 100 çalışmayı yinelemeye çalıştığı projede, özgün çalışmaların yaklaşık ne kadarı anlamlı sonuçla yinelenebilmiştir?', 'Yaklaşık üçte biri', ['Neredeyse tamamı', 'Yaklaşık yüzde 5\'i', 'Yaklaşık yüzde 90\'ı ve etkilerin büyüklüğü de tamamen aynı kalmıştır'], 'Yinelemelerin yaklaşık yüzde 36\'sı istatistiksel olarak anlamlı sonuç vermiş; bu da sosyal psikolojide \'yineleme krizi\' tartışmalarını yoğunlaştırmıştır.'),
  ('Amerika\'da yapılan jüri araştırmalarına göre jüri müzakereleri sonucunda kararın genellikle hangi yönde verildiği bulunmuştur?', 'Müzakere öncesindeki ilk oylamada çoğunluğun eğilimi yönünde', ['İlk oylamada azınlıkta kalan görüş yönünde', 'Her zaman beraat yönünde', 'Jüri başkanının kişisel görüşü yönünde, çoğunluğun görüşünden bağımsız olarak'], 'Kalven ve Zeisel\'in çalışmaları, jürilerin büyük çoğunluğunun ilk oylamadaki çoğunluk görüşüyle karar verdiğini göstermiştir; azınlığın kararı çevirmesi seyrektir.'),
  ('Leon Festinger, sosyal karşılaştırma ve bilişsel çelişki kuramlarını geliştirmeden önce hangi ünlü sosyal psikoloğun öğrencisi olmuştur?', 'Kurt Lewin', ['Solomon Asch', 'Stanley Milgram', 'Henri Tajfel'], 'Festinger, Lewin\'in Iowa Üniversitesi\'ndeki öğrencisiydi ve onunla birlikte MIT\'deki Grup Dinamiği Araştırma Merkezi\'nde çalıştı.'),
  ('Gordon Allport ve Leo Postman\'ın 1947\'de söylentiler üzerine yaptıkları çalışmalarda, bir öykü kişiden kişiye aktarıldıkça ayrıntıların kaybolup öykünün kısalmasına ne ad verilmiştir?', 'Düzleştirme', ['Keskinleştirme', 'Özümleme', 'Abartma ve yeni ayrıntılar ekleme'], 'Allport ve Postman\'a göre söylenti aktarılırken düzleştirme (ayrıntı kaybı), keskinleştirme (kalan ayrıntıların vurgulanması) ve özümleme (beklentilere uydurma) süreçleri işler.'),
  ('Allport ve Postman\'ın söylenti çalışmasında, bir resimde ustura tutan beyaz bir adamın, öykü aktarıldıkça bazı katılımcılarca usturayı siyahi adamın tuttuğu biçiminde anlatılması hangi süreci gösterir?', 'Özümleme', ['Düzleştirme', 'Keskinleştirme', 'Sosyal kolaylaştırma ve izleyicinin etkisi'], 'Özümlemede aktarılan bilgi, aktaranın kalıp yargı ve beklentilerine uyacak biçimde çarpıtılır.'),
  ('Alex Bavelas ve Harold Leavitt\'in iletişim ağı deneylerinde, bütün iletişimin merkezdeki bir kişi üzerinden geçtiği \'tekerlek\' ağı basit görevlerde hangi sonucu vermiştir?', 'Hızlı ve az hatalı çözüm, ama çevredeki üyelerde düşük doyum', ['Yavaş ve çok hatalı çözüm', 'Bütün üyelerde çok yüksek doyum', 'Görevin hiçbir zaman çözülememesi ve grubun kısa sürede dağılması'], 'Merkezî ağlar basit görevlerde verimli olsa da merkezdeki kişi dışındakilerin doyumunu düşürür; karmaşık görevlerde ise merkezdeki kişi aşırı yüklenebilir.'),
  ('Moreland ve Levine\'in grup sosyalleşmesi modelinde, bir kişinin gruba tam üye olarak kabul edilmesinden önce grubun ve kişinin birbirini değerlendirdiği ilk evre hangisidir?', 'Araştırma', ['Sürdürme', 'Yeniden sosyalleşme', 'Anma ve ayrılıktan sonraki hatırlama dönemi'], 'Model araştırma, sosyalleşme, sürdürme, yeniden sosyalleşme ve anma evrelerinden oluşur; her geçişte bağlılık düzeyi değişir.'),
  ('Driscoll, Davis ve Lipetz\'in 1972 çalışmasında, ailelerin karşı çıktığı çiftlerin romantik sevgisinin bir süre sonra arttığı bulunmuştur. Bu \'Romeo ve Juliet etkisi\' en iyi hangi kavramla açıklanır?', 'Tepkisellik', ['Salt maruz kalma', 'Sosyal kaytarma', 'Seyirci etkisi ve sorumluluğun dağılması'], 'Ailenin müdahalesi çiftin seçim özgürlüğünü tehdit ettiğinde, ilişki daha değerli görünür ve bağlılık artabilir.'),
  ('Levine ve arkadaşlarının 2005 çalışmasında, Manchester United taraftarı katılımcılar koşarken düşüp yaralanan birine, yaralı hangi formayı giydiğinde daha çok yardım etmiştir?', 'Kendi takımlarının forması', ['Rakip takımın forması', 'Düz, markasız bir tişört', 'Yalnızca bir koşu kulübünün logosunu taşıyan formalar'], 'Katılımcılar iç grup üyesi olarak gördükleri kişiye daha çok yardım etmiş; ortak \'futbol taraftarı\' kimliği vurgulandığında ise rakip formalıya yardım da artmıştır.'),
  ('Eagly ve Crowley\'nin meta-analizine göre erkeklerin yabancılara yardım etme olasılığının kadınlardan yüksek bulunduğu durumlar genellikle hangileridir?', 'Fiziksel risk içeren ve kahramanlık gerektiren acil durumlar', ['Uzun süreli bakım ve duygusal destek gerektiren durumlar', 'Yakın arkadaşlara verilen duygusal destek', 'Hasta bir akrabaya yıllarca bakmak ve onun ihtiyaçlarını karşılamak'], 'Toplumsal cinsiyet rolleri yardım biçimlerini etkiler: Erkekler daha çok yabancılara yönelik kahramanca yardımlarda, kadınlar ise uzun süreli bakım ve destekte öne çıkar.'),
  ('Allan Wicker\'ın 1969\'daki derleme çalışması, tutumlar ile davranışlar arasındaki ilişki hakkında hangi sonuca varmıştır?', 'İlişkinin beklenenden çok daha zayıf olduğu', ['Tutumların davranışı neredeyse kusursuz yordadığı', 'Tutum ile davranış arasında ters yönlü güçlü bir ilişki olduğu', 'Tutumların yalnızca çocukların davranışlarını yordadığı, yetişkinlerinkini hiç yordamadığı'], 'Wicker\'ın derlemesi tutum-davranış korelasyonlarının genellikle düşük olduğunu göstermiş ve tutumların hangi koşullarda davranışı yordadığına dair araştırmaları başlatmıştır.'),
  ('Bir araştırmada katılımcılara bir kahve kupası verilmiş, sonra bu kupayı satmak için istedikleri fiyatın, kupası olmayanların aynı kupa için ödemeye razı oldukları fiyattan çok daha yüksek olduğu görülmüştür. Bu olguya ne ad verilir?', 'Sahiplik etkisi', ['Salt maruz kalma etkisi', 'Aşırı gerekçelendirme', 'Kıtlık ilkesi ve az bulunanın değeri'], 'İnsanlar sahip oldukları nesnelere, yalnızca onlara sahip oldukları için daha fazla değer biçer.'),
  ('İyi bir ruh halindeki kişilerin ikna mesajlarını genellikle daha yüzeysel işlediği, zayıf argümanlardan da etkilenebildiği bulunmuştur. Bunun olası açıklaması hangisidir?', 'İyi ruh halinin dikkatli düşünme gereksinimini azaltması', ['İyi ruh halinin kişiyi daha eleştirel yapması', 'Ruh halinin iknayla hiç ilgisi olmaması', 'İyi ruh halinin kişiyi mesajı hiç duymaz hale getirmesi ve kulaklarını tıkaması'], 'Olumlu duygu her şeyin yolunda olduğunu işaret eder; bu da kişinin mesajı ayrıntılı incelemek yerine kestirmelere başvurmasına yol açabilir.'),
  ('Henrich, Heine ve Norenzayan\'ın 2010 tarihli makalesinde psikoloji araştırmalarının katılımcıları için kullandıkları \'WEIRD\' kısaltması hangi özellikleri anlatır?', 'Batılı, eğitimli, sanayileşmiş, zengin ve demokratik toplumlardan gelme', ['Genç, kadın, kentli ve öğrenci olma', 'Yaşlı, emekli, kırsal ve az eğitimli olma', 'Çocuk, ergen ve genç yetişkinlerin karışımından oluşan, farklı ülkelerden seçilmiş örneklem'], 'Yazarlar, araştırmaların büyük bölümünün dünya nüfusunun küçük ve sıra dışı bir kesiminden elde edildiğini ve bulguların evrenselliğinin sorgulanması gerektiğini vurgulamıştır.'),
  ('İyi bir iş yaptıktan sonra insanların sonraki fırsatta daha az ahlaki davranabildiğini gösteren, örneğin bağış yaptıktan sonra küçük bir kuralı çiğnemeyi kendine hak görme biçimindeki olguya ne ad verilir?', 'Ahlaki lisanslama', ['Aşırı gerekçelendirme', 'Kendini doğrulama', 'Ahlaki aşılama ve önceden direnç kazanma'], 'Ahlaki lisanslamada kişi önceki iyi davranışının kendisine bir tür \'kredi\' sağladığını hisseder ve sonraki etik dışı davranışı daha kolay gerekçelendirir.'),
  ('Richard Crutchfield\'ın 1955\'te Asch deneyini geliştirerek katılımcıları ayrı kabinlere yerleştirip diğerlerinin yanıtlarını ışıklı bir panelde gösterdiği düzeneğin avantajı neydi?', 'Aynı anda çok sayıda katılımcıyı iş birlikçi kullanmadan test edebilmek', ['Katılımcıların birbirini yüz yüze görmesini sağlamak', 'Uymayı tamamen ortadan kaldırmak', 'Deneyi yalnızca hayvanlarla yapabilmek ve insanları dışarıda tutmak'], 'Crutchfield düzeneğinde her katılımcı ötekilerin yanıtı sandığı sahte ışıkları görür; böylece iş birlikçiye gerek kalmadan aynı anda birçok kişi test edilebilir.'),
  ('Cialdini\'nin 2016\'da \'Pre-Suasion\' kitabında uyum sağlatma ilkelerine eklediği yedinci ilke hangisidir?', 'Birlik', ['Kıtlık', 'Otorite', 'Karşılıklılık'], 'Birlik ilkesi, insanların aile, memleket ya da inanç gibi ortak bir kimliği paylaştıklarını hissettikleri kişilerden daha kolay etkilendiğini anlatır.'),
  ('Shotland ve Straw\'ın 1976 deneyinde bir kadın ile erkek arasında geçen sahte bir kavgayı izleyen katılımcılar, kadın \'Seni tanımıyorum!\' diye bağırdığında, \'Seninle neden evlendim bilmiyorum!\' diye bağırdığına göre çok daha sık müdahale etmiştir. Bu bulgu yardım modelinin hangi aşamasıyla ilgilidir?', 'Olayı acil durum olarak yorumlama', ['Olayı fark etme', 'Yardımı uygulamak için gerekli beceriye sahip olma', 'Yardım etmenin maliyetini hesaplayıp parasal ödül beklemek'], 'Kavga bir karı-koca tartışması olarak yorumlandığında özel bir aile meselesi sayılmış ve acil durum olarak algılanmamıştır; bu da müdahaleyi azaltmıştır.'),
  ('Kurt Lewin\'in alan kuramında kişinin belli bir andaki davranışını etkileyen bütün psikolojik etkenlerin toplamını anlatan kavram hangisidir?', 'Yaşam alanı', ['Kişisel alan', 'Kabul alanı', 'Mahrem alan ve aile çevresi'], 'Lewin\'e göre davranış, kişinin o andaki ihtiyaçlarını, hedeflerini ve algıladığı çevreyi içeren yaşam alanının bir fonksiyonudur.'),
  ('Engellenme-saldırganlık hipotezini 1939\'da \'Frustration and Aggression\' adlı kitapla ortaya atan araştırmacılar hangi üniversitede çalışıyordu?', 'Yale Üniversitesi', ['Harvard Üniversitesi', 'Oxford Üniversitesi', 'Sorbonne Üniversitesi ve Paris\'teki enstitüler'], 'John Dollard, Leonard Doob, Neal Miller, Orval Mowrer ve Robert Sears\'tan oluşan Yale grubu hipotezi ilk biçimiyle ortaya koymuştur.'),
  ('Robert Levine\'in 1990\'larda 23 büyük kentte düşürülen kalem, yardım isteyen engelli kişi gibi durumlarla yaptığı alan araştırmasında, yabancılara yardımın en yüksek olduğu kentler arasında hangisi yer almıştır?', 'Rio de Janeiro', ['New York', 'Kuala Lumpur', 'Amsterdam ve diğer Kuzey Avrupa kentleri'], 'Levine\'in çalışmasında Rio de Janeiro ve San José gibi \'simpatia\' değerinin öne çıktığı kentler en yardımsever bulunmuş; Kuala Lumpur ve New York listenin sonlarında yer almıştır.'),
  ('Holt-Lunstad ve arkadaşlarının 2010\'da 148 çalışmayı birleştiren meta-analizi sosyal ilişkiler ile sağlık arasında hangi sonucu ortaya koymuştur?', 'Güçlü sosyal ilişkileri olanların hayatta kalma olasılığının belirgin biçimde yüksek olduğu', ['Sosyal ilişkilerin ömrü kısalttığı', 'Sosyal ilişkilerin sağlıkla hiçbir ilişkisinin olmadığı', 'Yalnızca evli kişilerin daha uzun yaşadığı, arkadaşlıkların ise hiçbir etkisinin olmadığı'], 'Meta-analiz, güçlü sosyal ilişkilerin hayatta kalma olasılığını yaklaşık yüzde 50 artırdığını ve sosyal yalnızlığın etkisinin sigara gibi bilinen risk etkenleriyle karşılaştırılabilir olduğunu göstermiştir.'),
  ('Liderlik araştırmalarında, lider olmayan gruplarda en çok konuşan kişinin, söylediklerinin niteliğinden bağımsız olarak lider olarak algılanma eğilimine ne ad verilir?', 'Gevezelik (konuşma miktarı) etkisi', ['Kaçınma etkisi', 'Uyuyan etki', 'Kara koyun etkisi ve sapanın dışlanması'], 'Araştırmalar, grup tartışmalarında konuşma süresinin lider olarak seçilmeyi güçlü biçimde yordadığını göstermiştir; bu bulgu \'gevezelik hipotezi\' olarak bilinir.'),
  ('Osgood ve Tannenbaum\'un uyum (congruity) kuramına göre, çok sevilen bir kaynak çok sevilmeyen bir görüşü desteklediğinde ne olması beklenir?', 'Kaynağa yönelik beğeni azalırken görüşe yönelik tutum olumluya doğru kayar', ['Kaynak daha çok sevilir, görüş daha çok reddedilir', 'Hiçbir tutumda değişiklik olmaz', 'Kaynak tamamen unutulur ve görüş hakkında hiçbir yargıda bulunulmaz'], 'Uyum kuramı, iki tutumun birbirine doğru kaydığını ve daha uç olan tutumun daha az değiştiğini öngörür; bu, denge kuramına niceliksel bir boyut ekler.'),
  ('Asch\'in çizgi deneyindeki gerçek katılımcının masadaki konumu genellikle nasıl ayarlanmıştı?', 'Sondan bir önceki ya da son sıralarda yanıt verecek biçimde', ['Her zaman ilk yanıt verecek biçimde', 'Odanın dışında, telefonla', 'Hiç yanıt vermeyip yalnızca gözlemleyecek biçimde, yanıtları kaydederek'], 'Gerçek katılımcı, iş birlikçilerin çoğunun yanlış yanıtını duyduktan sonra yanıt verecek bir sıraya oturtularak grup baskısıyla karşı karşıya bırakılmıştır.'),
  ('Henri Tajfel\'in sosyal kimlik ve önyargı üzerine çalışmalarını biçimlendiren kişisel yaşam deneyimi hangisidir?', 'Polonya doğumlu bir Yahudi olarak İkinci Dünya Savaşı\'nda ailesini Holokost\'ta yitirmesi', ['Amerika\'da bir çiftlikte büyümesi', 'Japonya\'da diplomat olarak çalışması', 'Uzun yıllar boyunca Antarktika\'da bir araştırma istasyonunda yalnız yaşaması ve çalışması'], 'Tajfel savaş esiri olarak hayatta kalmış, ailesinin büyük bölümünü Holokost\'ta yitirmiş; bu deneyim onun gruplar arası ayrımcılığı anlama çabasının temelini oluşturmuştur.'),
  ('\'Bireysizleşme\' kavramını sosyal psikolojiye ilk kez 1952\'de kazandıran araştırmacılar arasında kim yer alır?', 'Leon Festinger', ['Stanley Milgram', 'Robert Cialdini', 'Daniel Batson'], 'Festinger, Pepitone ve Newcomb 1952\'de grup içinde bireylerin kimliklerinin silikleşmesini \'bireysizleşme\' olarak adlandırmıştır.'),
  ('Isen ve arkadaşlarının araştırmalarına göre küçük bir armağan almanın yarattığı olumlu ruh halinin yardım etmeyi artırıcı etkisi ne kadar sürmüştür?', 'Kısa süreli; yaklaşık yirmi dakika içinde kaybolmuştur', ['Haftalarca aynı güçte sürmüştür', 'Hiç ortaya çıkmamıştır', 'Yıllarca sürmüş ve kişilerin kalıcı bir özelliğine dönüşmüştür'], 'İyi hissetme ile yardım etme arasındaki bağ gerçek olsa da olumlu ruh hali geçtikçe hızla zayıflar; Isen\'in çalışmasında etki yaklaşık 20 dakikada ortadan kalkmıştır.'),
  ('Darley ve Latané\'nin seyirci müdahalesi üzerine yaptıkları çalışmaları bir araya getirdikleri 1970 tarihli kitabın adı nedir?', 'The Unresponsive Bystander', ['The Nature of Prejudice', 'Obedience to Authority', 'When Prophecy Fails'], 'Latané ve Darley 1970\'te \'The Unresponsive Bystander: Why Doesn\'t He Help?\' adlı kitapta yardım etme karar modelini ve deneylerini ayrıntılı biçimde sunmuştur.'),
  ('Robbers Cave başta olmak üzere birçok çalışmayı Muzafer Şerif ile birlikte yürüten ve sosyal yargı kuramının geliştirilmesine katkıda bulunan sosyal psikolog kimdir?', 'Carolyn Wood Sherif', ['Mamie Clark', 'Elaine Hatfield', 'Alice Eagly'], 'Carolyn Wood Sherif, eşi Muzafer Şerif ile gruplar arası ilişkiler ve sosyal yargı kuramı üzerine ortak çalışmalar yapmış, ayrıca toplumsal cinsiyet araştırmalarına katkıda bulunmuştur.'),
];
